                "bearer": []
              }
            ]
          }
        },
        "/v3/plans/{id}/confirm": {
          "get": {
            "summary": "Confirm execution status",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v1/plans": {
          "post": {
            "summary": "DEPRECATED draft create",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        }
      }
    }
